<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Register — Public Service</title>
<style>
*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}
:root{--navy:#0a2540;--navy-light:#14365e;--orange:#e87722;--orange-dark:#c9641a;--bg:#eef2f7;--panel:#fff;--text:#1a2b42;--muted:#5a6b80;--error:#c0392b;--success:#1a8a5c;--border:#c5d0de;--focus:#e87722}
body{font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;background:var(--bg);color:var(--text);line-height:1.5;min-height:100vh;display:flex;flex-direction:column}
header.service-header{background:var(--navy);width:100%;padding:1.25rem 1.5rem;display:flex;align-items:center;gap:.75rem}
header.service-header .logo{width:32px;height:32px;background:var(--orange);border-radius:6px;display:flex;align-items:center;justify-content:center;color:#fff;font-weight:700;font-size:1.1rem;flex-shrink:0}
header.service-header h1{color:#fff;font-size:1.25rem;font-weight:600;letter-spacing:.02em}
header.service-header .accent-bar{margin-left:auto;width:48px;height:4px;background:var(--orange);border-radius:2px}
main{flex:1;display:flex;align-items:center;justify-content:center;padding:2rem 1rem}
.panel{background:var(--panel);border-radius:12px;box-shadow:0 4px 24px rgba(10,37,64,.1);padding:2rem;width:100%;max-width:640px}
.panel h2{font-size:1.5rem;margin-bottom:.25rem;color:var(--navy)}
.panel .subtitle{color:var(--muted);font-size:.9rem;margin-bottom:1.5rem}
.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:1rem 1.25rem}
.field{display:flex;flex-direction:column;gap:.3rem}
.field.full{grid-column:1/-1}
.field.dob{grid-column:1}
label{font-size:.85rem;font-weight:600;color:var(--navy)}
input[type=text],input[type=email],input[type=date],input[type=password]{width:100%;padding:.6rem .75rem;border:1.5px solid var(--border);border-radius:8px;font-size:.95rem;font-family:inherit;color:var(--text);background:#fff;transition:border-color .15s,box-shadow .15s}
input:focus{outline:none;border-color:var(--focus);box-shadow:0 0 0 3px rgba(232,119,34,.15)}
input[aria-invalid="true"]{border-color:var(--error)}
input[aria-invalid="true"]:focus{box-shadow:0 0 0 3px rgba(192,57,43,.15)}
.error-msg{color:var(--error);font-size:.8rem;min-height:1rem;display:none}
.error-msg.show{display:block}
.hint{color:var(--muted);font-size:.78rem}
.pw-wrap{position:relative}
.pw-wrap input{padding-right:2.75rem}
.pw-toggle{position:absolute;right:.5rem;top:50%;transform:translateY(-50%);background:none;border:none;color:var(--navy);cursor:pointer;font-size:.78rem;font-weight:600;padding:.25rem .4rem;border-radius:4px}
.pw-toggle:hover{background:var(--bg)}
.pw-toggle:focus{outline:2px solid var(--focus);outline-offset:1px}
.pw-strength{font-size:.78rem;margin-top:.2rem;min-height:1rem}
.pw-strength.weak{color:var(--error)}
.pw-strength.fair{color:#d4a017}
.pw-strength.strong{color:var(--success)}
.checkbox-field{display:flex;align-items:flex-start;gap:.6rem;grid-column:1/-1}
.checkbox-field input[type=checkbox]{width:18px;height:18px;margin-top:.15rem;accent-color:var(--orange);cursor:pointer;flex-shrink:0}
.checkbox-field label{font-size:.88rem;font-weight:400;color:var(--text);cursor:pointer}
.checkbox-field label a{color:var(--orange-dark);text-decoration:underline}
.checkbox-field .error-msg{margin-top:.2rem}
.submit-row{grid-column:1/-1;margin-top:.5rem}
button[type=submit]{width:100%;padding:.8rem 1.5rem;background:var(--orange);color:#fff;border:none;border-radius:8px;font-size:1rem;font-weight:600;cursor:pointer;transition:background .15s,transform .05s}
button[type=submit]:hover{background:var(--orange-dark)}
button[type=submit]:active{transform:scale(.98)}
button[type=submit]:focus{outline:none;box-shadow:0 0 0 3px rgba(232,119,34,.3)}
button[type=submit]:disabled{background:#b0b8c4;cursor:not-allowed}
.success-banner{background:#e6f5ee;border:1.5px solid var(--success);color:var(--success);padding:.8rem 1rem;border-radius:8px;margin-bottom:1.25rem;font-size:.9rem;display:none}
.success-banner.show{display:block}
.dup-banner{background:#fef3e8;border:1.5px solid var(--orange);color:var(--orange-dark);padding:.8rem 1rem;border-radius:8px;margin-bottom:1.25rem;font-size:.9rem;display:none}
.dup-banner.show{display:block}
@media(max-width:560px){.form-grid{grid-template-columns:1fr}.field.dob{grid-column:1}.panel{padding:1.5rem 1.25rem}}
.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);border:0}
</style>
</head>
<body>
<header class="service-header" role="banner">
<div class="logo" aria-hidden="true">P</div>
<h1>Public Service Portal</h1>
<div class="accent-bar" aria-hidden="true"></div>
</header>
<main>
<div class="panel">
<h2>Create your account</h2>
<p class="subtitle">Fill in the details below to register.</p>
<div class="success-banner" id="successBanner" role="status" aria-live="polite"></div>
<div class="dup-banner" id="dupBanner" role="alert" aria-live="assertive"></div>
<form id="regForm" novalidate>
<div class="form-grid">
<div class="field">
<label for="username">Username</label>
<input type="text" id="username" name="username" autocomplete="username" required minlength="3" maxlength="20" aria-describedby="usernameErr">
<div class="error-msg" id="usernameErr" role="alert"></div>
</div>
<div class="field">
<label for="email">Email address</label>
<input type="email" id="email" name="email" autocomplete="email" required aria-describedby="emailErr">
<div class="error-msg" id="emailErr" role="alert"></div>
</div>
<div class="field dob">
<label for="dob">Date of birth <span class="hint">(optional)</span></label>
<input type="date" id="dob" name="dob" aria-describedby="dobErr">
<div class="error-msg" id="dobErr" role="alert"></div>
</div>
<div class="field">
<label for="password">Password</label>
<div class="pw-wrap">
<input type="password" id="password" name="password" autocomplete="new-password" required aria-describedby="passwordErr pwStrength">
<button type="button" class="pw-toggle" id="pwToggle" aria-label="Show password">Show</button>
</div>
<div class="error-msg" id="passwordErr" role="alert"></div>
<div class="pw-strength" id="pwStrength" aria-live="polite"></div>
</div>
<div class="field full">
<label for="confirmPassword">Confirm password</label>
<div class="pw-wrap">
<input type="password" id="confirmPassword" name="confirmPassword" autocomplete="new-password" required aria-describedby="confirmErr">
<button type="button" class="pw-toggle" id="cpwToggle" aria-label="Show confirm password">Show</button>
</div>
<div class="error-msg" id="confirmErr" role="alert"></div>
</div>
<div class="checkbox-field">
<input type="checkbox" id="terms" name="terms" required aria-describedby="termsErr">
<label for="terms">I accept the <a href="#" onclick="return false">Terms of Service</a> and Privacy Policy.</label>
<div class="error-msg" id="termsErr" role="alert"></div>
</div>
<div class="submit-row">
<button type="submit" id="submitBtn">Create account</button>
</div>
</div>
</form>
</div>
</main>
<script>
(function(){
const form=document.getElementById('regForm');
const STORE_KEY='registered_users';
const successBanner=document.getElementById('successBanner');
const dupBanner=document.getElementById('dupBanner');

function getUsers(){try{return JSON.parse(localStorage.getItem(STORE_KEY))||[]}catch(e){return[]}}
function saveUsers(u){localStorage.setItem(STORE_KEY,JSON.stringify(u))}
function showError(id,msg){const el=document.getElementById(id);if(msg){el.textContent=msg;el.classList.add('show')}else{el.textContent='';el.classList.remove('show')}}
function setInvalid(inputId,invalid){document.getElementById(inputId).setAttribute('aria-invalid',invalid?'true':'false')}

function validateUsername(){
const v=document.getElementById('username').value.trim();
if(!v){showError('usernameErr','Username is required.');setInvalid('username',true);return false}
if(v.length<3){showError('usernameErr','Username must be at least 3 characters.');setInvalid('username',true);return false}
if(v.length>20){showError('usernameErr','Username must be 20 characters or fewer.');setInvalid('username',true);return false}
if(!/^[a-zA-Z0-9_]+$/.test(v)){showError('usernameErr','Use only letters, numbers, and underscores.');setInvalid('username',true);return false}
showError('usernameErr','');setInvalid('username',false);return true}
function validateEmail(){
const v=document.getElementById('email').value.trim();
if(!v){showError('emailErr','Email is required.');setInvalid('email',true);return false}
if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v)){showError('emailErr','Enter a valid email address.');setInvalid('email',true);return false}
showError('emailErr','');setInvalid('email',false);return true}
function validateDob(){
const v=document.getElementById('dob').value;
if(!v){showError('dobErr','');document.getElementById('dob').removeAttribute('aria-invalid');return true}
const d=new Date(v+'T00:00:00');const now=new Date();
if(isNaN(d.getTime())){showError('dobErr','Enter a valid date.');setInvalid('dob',true);return false}
if(d>now){showError('dobErr','Date of birth cannot be in the future.');setInvalid('dob',true);return false}
const minDate=new Date('1900-01-01');
if(d<minDate){showError('dobErr','Enter a date after 1900.');setInvalid('dob',true);return false}
showError('dobErr','');setInvalid('dob',false);return true}
function passwordStrength(v){
let s=0;if(v.length>=8)s++;if(v.length>=12)s++;if(/[a-z]/.test(v)&&/[A-Z]/.test(v))s++;if(/\d/.test(v))s++;if(/[^a-zA-Z0-9]/.test(v))s++;return s}
function validatePassword(){
const v=document.getElementById('password').value;
const stEl=document.getElementById('pwStrength');
if(!v){showError('passwordErr','Password is required.');setInvalid('password',true);stEl.textContent='';return false}
if(v.length<8){showError('passwordErr','Password must be at least 8 characters.');setInvalid('password',true);stEl.textContent='';return false}
showError('passwordErr','');setInvalid('password',false);
const s=passwordStrength(v);
stEl.className='pw-strength';
if(s<=2){stEl.classList.add('weak');stEl.textContent='Weak password — add length, mixed case, numbers, and symbols.'}
else if(s<=3){stEl.classList.add('fair');stEl.textContent='Fair password strength.'}
else{stEl.classList.add('strong');stEl.textContent='Strong password.'}
return true}
function validateConfirm(){
const v=document.getElementById('confirmPassword').value;
const p=document.getElementById('password').value;
if(!v){showError('confirmErr','Please confirm your password.');setInvalid('confirmPassword',true);return false}
if(v!==p){showError('confirmErr','Passwords do not match.');setInvalid('confirmPassword',true);return false}
showError('confirmErr','');setInvalid('confirmPassword',false);return true}
function validateTerms(){
const c=document.getElementById('terms').checked;
if(!c){showError('termsErr','You must accept the Terms of Service.');return false}
showError('termsErr','');return true}

function checkDuplicate(username,email){
const users=getUsers();
return users.some(u=>u.username.toLowerCase()===username.toLowerCase()||u.email.toLowerCase()===email.toLowerCase())}

form.addEventListener('submit',function(e){
e.preventDefault();
successBanner.classList.remove('show');dupBanner.classList.remove('show');
const ok=[validateUsername(),validateEmail(),validateDob(),validatePassword(),validateConfirm(),validateTerms()];
if(ok.some(v=>!v)){const firstInvalid=form.querySelector('[aria-invalid="true"], .checkbox-field input:not(:checked)');if(firstInvalid)firstInvalid.focus();return}
const username=document.getElementById('username').value.trim();
const email=document.getElementById('email').value.trim();
if(checkDuplicate(username,email)){
dupBanner.textContent='An account with this username or email already exists. Please use a different one or log in.';
dupBanner.classList.add('show');dupBanner.focus();return}
const dob=document.getElementById('dob').value;
const users=getUsers();
users.push({username:username,email:email,dob:dob||null,createdAt:new Date().toISOString()});
saveUsers(users);
form.reset();
document.querySelectorAll('[aria-invalid]').forEach(el=>el.removeAttribute('aria-invalid'));
document.getElementById('pwStrength').textContent='';
successBanner.textContent='Registration successful! Welcome, '+username+'. You can now sign in.';
successBanner.classList.add('show');successBanner.focus();});

['username','email','dob','password','confirmPassword'].forEach(id=>{
document.getElementById(id).addEventListener('blur',function(){
if(id==='username')validateUsername();
else if(id==='email')validateEmail();
else if(id==='dob')validateDob();
else if(id==='password')validatePassword();
else if(id==='confirmPassword')validateConfirm();});
document.getElementById(id).addEventListener('input',function(){
const errId=id+'Err';showError(errId,'');document.getElementById(id).removeAttribute('aria-invalid');
if(id==='password'){const v=this.value;if(v){const s=passwordStrength(v);const stEl=document.getElementById('pwStrength');stEl.className='pw-strength';if(s<=2){stEl.classList.add('weak');stEl.textContent='Weak'}else if(s<=3){stEl.classList.add('fair');stEl.textContent='Fair'}else{stEl.classList.add('strong');stEl.textContent='Strong'}}else{stEl.textContent=''}}});});
document.getElementById('terms').addEventListener('change',validateTerms);

function setupToggle(btnId,inputId){
const btn=document.getElementById(btnId),inp=document.getElementById(inputId);
btn.addEventListener('click',function(){
if(inp.type==='password'){inp.type='text';btn.textContent='Hide';btn.setAttribute('aria-label',btnId==='pwToggle'?'Hide password':'Hide confirm password')}
else{inp.type='password';btn.textContent='Show';btn.setAttribute('aria-label',btnId==='pwToggle'?'Show password':'Show confirm password')}});}
setupToggle('pwToggle','password');
setupToggle('cpwToggle','confirmPassword');
})();
</script>
</body>
</html>


